(self.webpackChunkkernel_community=self.webpackChunkkernel_community||[]).push([[8997],{80558:function(e,t,n){"use strict";n.r(t),n.d(t,{_frontmatter:function(){return s},default:function(){return w}});var a=n(19756),o=(n(67294),n(63497)),i=n(60975),r=["components"],s={},l=function(e){return function(t){return console.warn("Component "+e+" was not imported, exported, or provided by MDXProvider as global scope"),(0,o.kt)("div",t)}},h=l("InfoBlock"),c=l("Box"),u=l("Link"),p=l("List"),m={_frontmatter:s},d=i.Z;function w(e){var t=e.components,n=(0,a.Z)(e,r);return(0,o.kt)(d,Object.assign({},m,n,{components:t,mdxType:"MDXLayout"}),(0,o.kt)("h1",{id:"🤯-meaning",style:{position:"relative"}},"🤯 Meaning",(0,o.kt)("a",{parentName:"h1",href:"#%F0%9F%A4%AF-meaning","aria-label":"🤯 meaning permalink",className:"anchor-link after"},(0,o.kt)("span",{parentName:"a"},"¶"))),(0,o.kt)("p",null,"Any meaning we can make is dynamic, not static. It is deeply contextual. It is bound to time and place and person. It is highly particular. Yet, a truly honest and courageous description of the personal can create an environment conducive to encountering some aspect of yourself in the work of another. In that singular moment of encounter, shared meaning can exist without belonging to you, or me, or the work which causes/effects it."),(0,o.kt)("p",null,"This inability to own or control is critical, because much like any language, no one person can say what Bitcoin or Ethereum or any other network means. This is very much a feature rather than a bug. That said, many people have pointed out that, because they are programmable, we can use Bitcoin or Ethereum to change what we mean by “money”. We can use Ethereum to change what we mean by “contract”. These are profound shifts. Though what exactly they’re shifting us toward is difficult to say, precisely because no one person can say it. The real shift arises over time due to communal use, practice, and interaction."),(0,o.kt)("h2",{id:"smooth-response",style:{position:"relative"}},"Smooth Response",(0,o.kt)("a",{parentName:"h2",href:"#smooth-response","aria-label":"smooth response permalink",className:"anchor-link after"},(0,o.kt)("span",{parentName:"a"},"¶"))),(0,o.kt)("p",null,"This is one of the core reasons Kernel will always resist definitive answers. Yet, we do like planting seeds. Here is the small kernel we’d like to offer in this big conversation: "),(0,o.kt)("blockquote",null,(0,o.kt)("p",{parentName:"blockquote"},(0,o.kt)("strong",{parentName:"p"},"Blockchains enable us to program money meaningfully, so we can distribute power, such that we can play with significantly different sociopolitical structures and get unstuck."))),(0,o.kt)("p",null,"One assumption this seed statement makes is that we are currently stuck. It is a phrase taken from David Graeber’s book ",(0,o.kt)("em",{parentName:"p"},(0,o.kt)("a",{parentName:"em",href:"/conversation/hospitality"},"The Dawn of Everything")),". Stuckness is our generation’s struggle: not some namable and countable enemy, not some particular evil we can all point to and agree on. We are stuck in old arrangements of power and authority, and spend all our energy debating who should rule us rather than how to rule ourselves and what ",(0,o.kt)("em",{parentName:"p"},"that")," kind of leadership would actually look like. Too many of us have forgotten our capacity to imagine and enact different ways of living together, because the responsibility required to wield meaningful agency feels overwhelming."),(0,o.kt)("p",null,"Being stuck looks like loneliness and competition in online spaces that race to the bottom of the brainstem with extractive incentives and manipulative algorithms. Being stuck looks like democracy which is practiced via the election of a single candidate from a few impoverished choices every four or so years. Being stuck looks like a few winning and everyone else losing in the games our society deems valuable. In fact, it looks like there being winners or losers at all, rather than the sort of incentives which help us keep the game of life being played, infinitely."),(0,o.kt)("p",null,"We would like to suggest that ",(0,o.kt)("strong",{parentName:"p"},"becoming less stuck is a worthwhile goal")," we can adopt in the pursuit of understanding all the many meanings we’d like to make as a diverse community of practice who value ",(0,o.kt)("a",{parentName:"p",href:"https://www.youtube.com/watch?v=n3R4ze2hesk"},"plurality")," and are not willing to settle on one, conclusive meaning."),(0,o.kt)("h2",{id:"what-does-money-mean",style:{position:"relative"}},"What Does Money Mean?",(0,o.kt)("a",{parentName:"h2",href:"#what-does-money-mean","aria-label":"what does money mean permalink",className:"anchor-link after"},(0,o.kt)("span",{parentName:"a"},"¶"))),(0,o.kt)("p",null,"What does it mean to ",(0,o.kt)("em",{parentName:"p"},"program money meaningfully"),"? Well, what does it mean to use language meaningfully? One way of looking at it is that words only mean anything because the community who uses them agrees that they do. So, meaningful language is both that which is readily understood ",(0,o.kt)("strong",{parentName:"p"},"and")," that which, in anticipating its own most likely interpretations and adapting its structure accordingly, reveals something novel or surprising in its otherwise ordinary operation."),(0,o.kt)("p",null,"Until 2009, money was not quite the same. A small group of largely unelected bureaucrats in combination with powerful financial executives and a select group of politicians got to define monetary policy and the way it plays out in the larger economy. Whether they do a good or bad job continues to be the subject of heated debate. "),(0,o.kt)("p",null,"What structural shifts need to happen in order for more people to contribute to what money means by virtue of how it is created, distributed, and used in the world gets less attention. Small wonder then that the meanings most people associate with money have to do with exclusivity, corruption, competition, scarcity, and the need to accumulate in order to be safe."),(0,o.kt)("p",null,"Programming money meaningfully might mean producing code that is responsible for creating and distributing value in ways people can understand ",(0,o.kt)("strong",{parentName:"p"},"and "),"which - in anticipating what people think money already is - surprises people with more ",(0,o.kt)("a",{parentName:"p",href:"/learn/module-5/prosocial-value"},"prosocial effects"),", such that more people can be involved and more meanings can be made in an ongoing and dynamic process. It also means telling stories about our code which invite different kinds of people and perspectives into its use and cultivate different kinds of social contracts. And it means participating with others in communities of practice committed to investigating what money could be made to mean if we were less stuck in our relationship to power."),(0,o.kt)("p",null,"Meaningful money is a multidimensional affair because it involves people, planet, narrative, and code. A shared global ledger run on distributed networks where our languages function in deterministic ways is the only medium currently available where we could create such meanings.  "),(0,o.kt)("h2",{id:"revealing-power",style:{position:"relative"}},"Revealing Power",(0,o.kt)("a",{parentName:"h2",href:"#revealing-power","aria-label":"revealing power permalink",className:"anchor-link after"},(0,o.kt)("span",{parentName:"a"},"¶"))),(0,o.kt)("p",null,"So, do blockchains only have to do with money? Obviously not, because programming money meaningfully is not an end in itself. It is a means to an end, where the end might be ",(0,o.kt)("strong",{parentName:"p"},"distributing power"),". Our seed suggestion implies that understanding what blockchains could mean entails understanding how power operates in the world and how that can realistically be reprogrammed."),(0,o.kt)("p",null,"How can we be intentional about who and what we empower with our code, our stories, and the ways in which we direct each other’s attention?"),(0,o.kt)("p",null,"To be clear, the crypto community has not done a wonderful job of this so far. The wealth distribution in our networks is often worse than in the most unequal countries on Earth. The way we create and distribute money is often woefully uncreative, if not downright manipulative. We often repeat and advance the most extractive patterns others of us might wish to evolve from."),(0,o.kt)("p",null,"To understand how this has happened, we can ask, “What is power?” Whether it is political, financial, social or otherwise, the simplest way to understand power is by considering its physical meaning. Power is defined by the amount of energy transferred in a given time: the less time it takes to transfer the same amount of energy, the greater is your power. If you can use the path of least resistance, you can transfer a lot of energy in a very short time. Therefore, the powerful are those with access to the channels that transfer significant energy without incurring high time costs. "),(0,o.kt)("p",null,"For instance, the Chair of the Federal Reserve can change US interest rates in a few weeks of meetings. You and I could try for a lifetime and still fail. We lack access to low resistance channels and so the time cost becomes exorbitant."),(0,o.kt)("p",null,"This is why blockchains are a viable medium for distributing power. They ",(0,o.kt)("a",{parentName:"p",href:"http://markburgess.org/promises.html"},"hold the promise of opening")," many more channels to transfer ",(0,o.kt)("a",{parentName:"p",href:"https://sign.kernel.community"},"significant")," energy with less resistance, which means a much greater chance of the kind of ongoing encounters with particular meaning courageously encoded that can illustrate genuinely shared truths. There are a few people ",(0,o.kt)("a",{parentName:"p",href:"https://www.youtube.com/watch?v=9ZToW_b9F-s"},"doing")," ",(0,o.kt)("a",{parentName:"p",href:"https://metacurrency.org/about/"},"this")," ",(0,o.kt)("a",{parentName:"p",href:"https://openmoney.org/top/omanifesto.html"},"already"),". We need more. Indeed, our ability to find solutions which genuinely enable people to make new meanings with money–which is equivalent to our ability to distribute power–will define the quality and scope of other applications we can build and the impact they will have. "),(0,o.kt)("p",null,"For instance, one cannot build meaningfully different social media if the underlying economic incentives are still extractive or competitive."),(0,o.kt)("h2",{id:"play-without-end",style:{position:"relative"}},"Play Without End",(0,o.kt)("a",{parentName:"h2",href:"#play-without-end","aria-label":"play without end permalink",className:"anchor-link after"},(0,o.kt)("span",{parentName:"a"},"¶"))),(0,o.kt)("p",null,"In fact, we might come to recognise that money is the most powerful social medium there is. It is the ultimate “",(0,o.kt)("a",{parentName:"p",href:"http://etheses.lse.ac.uk/4775/1/Merfield_201649740.pdf"},"social layer"),"”. In seeing this with clear eyes, it is perhaps possible to begin to play with power and the way we structure it sociopolitically. "),(0,o.kt)("p",null,"Once you see that this is what you’re doing when you’re writing a smart contract–that is, reprogramming power by virtue of how value flows through the functions your language executes–you might be less inclined to add ",(0,o.kt)("inlineCode",{parentName:"p"},"onlyOwner")," modifiers or repeat the same old structural relationships to authority and permission we all submit to, often unconsciously."),(0,o.kt)("p",null,"It’s important that this is approached with a sense of ",(0,o.kt)("a",{parentName:"p",href:"https://www.youtube.com/watch?v=9yVOd9TXNks"},"deep")," ",(0,o.kt)("a",{parentName:"p",href:"https://thebaffler.com/salvos/whats-the-point-if-we-cant-have-fun"},"playfulness"),". Play is not meant here as something trivial: ",(0,o.kt)("a",{parentName:"p",href:"https://blog.danfinlay.com/meme-tokens-and-consent/"},"yet another memecoin")," which has no deeper meaning, no surprise in its prosocial effects, no durable community of practice to make the transferred energy significantly enrich the quality of time its members can share."),(0,o.kt)("p",null,"Play is the spontaneous and joyful exploration of genuine alternatives which, in being aware of what is expected, happily inverts that to illustrate how conventional and conditioned our lives often are. It's not about pure speculation, or burning down the system, or using new tools to perpetuate the same traumas we have suffered because we can now exclude others from the games we make just like we were ourselves once excluded. Play, in being aware of expectations and nevertheless altering them, is about finding new and surprising balances in how we agree to arrange our lives together."),(0,o.kt)("p",null,"Perhaps such balances may be found somewhere between play and virtue? If we want to encode ",(0,o.kt)("a",{parentName:"p",href:"https://www.youtube.com/watch?v=WrKZAvOMZ14"},"the value of being unstuck")," into more meaningful monies, we will require both. We need play to become unstuck in a context of inflexible and outdated virtue. And we need virtue to become unstuck in a context of irresponsible play. This could look like crafting flexible systems, sensible to context and open to change despite (or, if you're really playful, ",(0,o.kt)("em",{parentName:"p"},"because of"),") the “permanent” medium in which they exist."),(0,o.kt)("p",null,"Here is one more",(0,o.kt)("br",{parentName:"p"}),"\n",(0,o.kt)("a",{parentName:"p",href:"https://avalonlibrary.net/ebooks/Ivan%20Illich%20-%20Celebration%20of%20Awareness%20-%20A%20Call%20for%20Institutional%20Revolution.pdf#page=40&zoom=auto,607,-231"},"powerless protocol"),",",(0,o.kt)("br",{parentName:"p"}),"\n","playfully designed to ask:   "),(0,o.kt)("p",null,"will you accept the poverty required",(0,o.kt)("br",{parentName:"p"}),"\n","to redefine wealth, to program money",(0,o.kt)("br",{parentName:"p"}),"\n","in meaningful ways which move",(0,o.kt)("br",{parentName:"p"}),"\n","with the times and do not resist,",(0,o.kt)("br",{parentName:"p"}),"\n","but open into channels where real value flows",(0,o.kt)("br",{parentName:"p"}),"\n","by virtue of the architecture",(0,o.kt)("br",{parentName:"p"}),"\n","participation promises? "),(0,o.kt)("p",null,"No force here,",(0,o.kt)("br",{parentName:"p"}),"\n","just an invitation",(0,o.kt)("br",{parentName:"p"}),"\n","to use the short time you have",(0,o.kt)("br",{parentName:"p"}),"\n","in service of true power."),(0,o.kt)("p",null,"It took a long time for the systems of money and the associated arrangements of power we live within to form. The work we are involved in here is generational, and deep meanings like these change slowly. This is not to deny the urgency with which we are called to enact change, it is simply to acknowledge that “",(0,o.kt)("a",{parentName:"p",href:"https://www.youtube.com/watch?v=m4XkmPxpogI"},"the times are urgent; we must slow down"),"”. This slowing down is not simply a decrease in velocity while still moving towards greater efficiency, productivity, and prosperity. It is a move in the minor key, a soft-shoe shuffle sidestep down a different direction given that we have reached the crossroads and must now look for radically new ways to live well together."),(0,o.kt)("p",null,"As we say elsewhere in Kernel, it is only when you are having the time of your life that you can invite others to join the game, and then you might really begin to live into the infinite meanings of this one, wild and precious life."),(0,o.kt)("h2",{id:"further-references",style:{position:"relative"}},"Further References",(0,o.kt)("a",{parentName:"h2",href:"#further-references","aria-label":"further references permalink",className:"anchor-link after"},(0,o.kt)("span",{parentName:"a"},"¶"))),(0,o.kt)(h,{mdxType:"InfoBlock"},(0,o.kt)(c,{mdxType:"Box"},(0,o.kt)("p",null,'"To know is to possess, and any fact is possessed by everyone who knows it, whereas those who ',(0,o.kt)("em",{parentName:"p"},"feel"),' truth are possessed, not possessors."'),(0,o.kt)("p",null,(0,o.kt)("img",{parentName:"p",src:"/images/ethereum.png",alt:"Ethereum Logo"})),(0,o.kt)(u,{to:"https://www.youtube.com/watch?v=kffo3pxNO7c",mdxType:"Link"},"ee cummings"))),(0,o.kt)(p,{mdxType:"List"},(0,o.kt)(u,{to:"https://www.youtube.com/watch?v=54l8_ewcOlY&list=PLND1JCRq8Vuh3f0P5qjrSdb5eC1ZfZwWJ",mdxType:"Link"},(0,o.kt)("p",null,"The Meaning Crisis")),(0,o.kt)(u,{to:"https://youtu.be/X_7U1ApSzaM?t=8103",mdxType:"Link"},(0,o.kt)("p",null,"Meaning is inseparable from reality. Love is an existential stance; a commitment."))))}w.isMDXComponent=!0}}]);
